<script setup>import TeamLogo from'../team/TeamLogo.vue';defineProps({game:Object,live:Boolean})</script><template><article class="game-card"><header><span v-if="live" class="live"><i class="live-dot"></i> LIVE / {{game.inning}}</span><span v-else>{{game.time}} / {{game.stadium}}</span><b>{{game.status}}</b></header><div class="team-row"><TeamLogo :team="game.away" :size="38"/><div><b>{{game.away.name}}</b><small>{{game.away.abbr}} / AWAY</small></div><strong v-if="live" class="mono">{{game.away.score}}</strong></div><div class="team-row"><TeamLogo :team="game.home" :size="38"/><div><b>{{game.home.name}}</b><small>{{game.home.abbr}} / HOME</small></div><strong v-if="live" class="mono">{{game.home.score}}</strong></div><div v-if="!live" class="context"><span><small>STARTERS</small>{{game.pitchers[0]}} / {{game.pitchers[1]}}</span><span><small>WEATHER</small>{{game.weather||'Pending'}}</span></div><footer><span>{{live?'Official live game feed':game.insight}}</span><RouterLink :to="live?`/live/${game.id}`:`/games/${game.id}`">{{live?'FOLLOW LIVE':'OPEN ANALYSIS'}} ↗</RouterLink></footer></article></template><style scoped>.game-card{border:1px solid var(--line);background:var(--surface);padding:15px;transition:.18s}.game-card:hover{border-color:var(--ink);transform:translateY(-2px)}header{display:flex;justify-content:space-between;gap:8px;border-bottom:1px solid var(--line);padding-bottom:11px;font:500 7px 'DM Mono';color:var(--muted)}header b{color:var(--text)}.live{display:flex;align-items:center;gap:7px;color:var(--orange)}.team-row{display:grid;grid-template-columns:40px 1fr auto;gap:9px;align-items:center;padding:11px 0;border-bottom:1px solid var(--line)}.team-row>div{display:flex;flex-direction:column;min-width:0}.team-row>div b{font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.team-row small{font:500 7px 'DM Mono';color:var(--muted);margin-top:3px}.team-row strong{font-size:25px;letter-spacing:-.08em}.context{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:12px 0}.context span{font-size:8px;line-height:1.45}.context small{display:block;font:500 7px 'DM Mono';color:var(--muted);margin-bottom:4px}footer{display:flex;justify-content:space-between;gap:10px;padding-top:11px;border-top:1px solid var(--line);font-size:8px;color:var(--muted)}footer a{font:600 7px 'DM Mono';color:var(--text);text-decoration:none;white-space:nowrap}@media(max-width:430px){.context{grid-template-columns:1fr}.context span:last-child{display:none}}</style>
